head.script:
// 테스트 설명, 유효성 값 설정
//  - _1 : 영역별 쓰임 + HTML 이스케이프
//  - _2 : Body 데이터 / defaultValue / 엑셀 다운로드 / 편집
//  - _3 : inputType 별 동작 (expression / checkbox / radio)
scwin.tData = {
    "description" : "[column > P > value]<br/>Column 에 표시하거나 사용할 값을 설정합니다.",
    "validation" : [
        "inputType='expression' 인 Column 의 표시값은 expression 속성의 표현식으로 다시 계산되므로 value 속성이 무시됩니다.",
        "inputType='checkbox','radio' 인 Body Column 은 trueValue 속성값과 value 속성값이 같으면 Column 값이 ''(Empty String)이어도 체크된 상태로 표시됩니다.",
    ]
}



scwin.onpageload = async function () {
    // Global DataList 생성 호출
    $c.gcm.createCommonDatalist();

    // 정적 select1 은 초기 selectedIndex 가 적용되지 않으므로 기본값 명시 설정 (value = Y, trueValue 와 같은 값)
    con_value.setSelectedIndex(1);

    // comp 초기 생성
    await scwin.comp_init();

    // 테스트 설명, 유효성 생성
    wf_body_left.getObj("scwin").createValidation(scwin.tData);
};



// 행 데이터 (4건)
//  - chk  : Row 1, 3 이 빈값
//  - rdo  : Row 1 만 빈값 (groupName 미설정 radio 는 모든 Row 가 같은 name 을 써서 한 Row 만 체크 표시되므로 빈값 Row 를 1개로 둔다)
//  - memo : Row 1, 3 이 빈값 (expression 표현식 display('memo') 의 원본)
scwin.rowPattern = [
    { "product" : "노트북", "chk" : "Y", "rdo" : "N", "memo" : "재고 확인" },
    { "product" : "모니터", "chk" : "", "rdo" : "", "memo" : "" },
    { "product" : "키보드", "chk" : "N", "rdo" : "N", "memo" : "입고 예정" },
    { "product" : "마우스", "chk" : "", "rdo" : "N", "memo" : "" }
];



// comp 생성
//  - chk(checkbox) / rdo(radio) : valueType=other, trueValue=Y, falseValue=N 고정 (valueType 미설정 시 trueValue 가 1 로 고정됨)
//  - memo(text)                 : expression 과 비교하기 위한 일반 Column
//  - expr(expression)           : expression=display('memo'), DataList 에 없는 Column
//  - con_value 는 chk / rdo / memo / expr 4개 Body Column 에 같은 값으로 적용
scwin.comp_init = async function () {
    // 기존 target / dataList / label 삭제
    if (typeof target1 !== 'undefined' && target1) {
        target1.remove();
    }
    if (typeof dlt_bind !== 'undefined' && dlt_bind) {
        $p.data.remove("dlt_bind");
    }
    if (typeof label1 !== 'undefined' && label1) {
        label1.remove();
    }

    // 테스트 정보 라벨 (target 생성 전 가장 먼저 생성)
    $c.gcm.createLabel('label="[전제] 체크 / 선택 Column 은 valueType=other, trueValue=Y, falseValue=N 고정, value 는 체크 / 선택 / 메모 / 계산 Column 에 같은 값으로 적용\n[전제] 계산 Column 은 inputType=expression, expression=display(memo) 로 메모 Column 값을 그대로 표시, 빈값 Row : 체크 Row 1, 3 / 선택 Row 1 / 메모 Row 1, 3\n[확인] (체크 상태 확인) 출력 : Row n 체크 상태 / chk 값 / 선택 상태 / rdo 값\n[확인] (표시값 확인) 출력 : Row n 메모 표시값 / 계산 표시값"', '', 'label1');

    // 조건 설정 (미설정 옵션은 속성 자체를 넣지 않는다)
    let cValue = con_value.getValue();
    let attrValue = (cValue === '') ? '' : ' value="' + cValue + '"';

    let strNameSpace = $c.gcm.getNameSpace();
    let grp_comp = $c.gcm.getTestGroup();

    // 바인딩 dataList (expr 은 DataList 에 없는 Column)
    let strDlt = '';
    strDlt += '<w2:dataList ' + strNameSpace + ' id="dlt_bind" baseNode="list" repeatNode="map">';
    strDlt += '<w2:columnInfo>';
    strDlt += '<w2:column id="product" name="상품" dataType="text"></w2:column>';
    strDlt += '<w2:column id="chk" name="체크" dataType="text"></w2:column>';
    strDlt += '<w2:column id="rdo" name="선택" dataType="text"></w2:column>';
    strDlt += '<w2:column id="memo" name="메모" dataType="text"></w2:column>';
    strDlt += '</w2:columnInfo>';
    strDlt += '<w2:data use="true"></w2:data>';
    strDlt += '</w2:dataList>';
    $p.data.create(strDlt);
    dlt_bind.setJSON(scwin.rowPattern, false);

    // target 생성
    let strTarget = '';
    strTarget += '<w2:gridView ' + strNameSpace + ' dataList="data:dlt_bind" id="" style="width:560px;height:170px;">';
    strTarget += '<w2:caption style="" id="caption1" value="this is a grid caption."></w2:caption>';
    strTarget += '<w2:header style="" id="header1">';
    strTarget += '<w2:row style="" id="row1">';
    strTarget += '<w2:column width="100" style="" inputType="text" id="column1" value="상품"></w2:column>';
    strTarget += '<w2:column width="90" style="" inputType="text" id="column2" value="체크 (checkbox)"></w2:column>';
    strTarget += '<w2:column width="90" style="" inputType="text" id="column3" value="선택 (radio)"></w2:column>';
    strTarget += '<w2:column width="130" style="" inputType="text" id="column4" value="메모 (text)"></w2:column>';
    strTarget += '<w2:column width="130" style="" inputType="text" id="column5" value="계산 (expression)"></w2:column>';
    strTarget += '</w2:row>';
    strTarget += '</w2:header>';
    strTarget += '<w2:gBody style="" id="gBody1">';
    strTarget += '<w2:row style="" id="row2">';
    strTarget += '<w2:column width="100" style="" inputType="text" id="product"></w2:column>';
    strTarget += '<w2:column width="90" style="" inputType="checkbox" id="chk" valueType="other" trueValue="Y" falseValue="N"' + attrValue + '></w2:column>';
    strTarget += '<w2:column width="90" style="" inputType="radio" id="rdo" valueType="other" trueValue="Y" falseValue="N"' + attrValue + '></w2:column>';
    strTarget += '<w2:column width="130" style="" inputType="text" id="memo"' + attrValue + '></w2:column>';
    strTarget += '<w2:column width="130" style="" inputType="expression" id="expr" expression="display(\'memo\')"' + attrValue + '></w2:column>';
    strTarget += '</w2:row>';
    strTarget += '</w2:gBody>';
    strTarget += '</w2:gridView>';

    scwin["target1"] = await $p.dynamicCreate(
        "target1",
        "gridView",
        strTarget,
        grp_comp
    );
}



// Body Cell td (rowIndex, Column ID)
scwin.getBodyTd = function (rowIndex, colId) {
    let colIndex = target1.getColumnIndex(colId);
    return document.querySelector("td[id='" + target1.id + "_cell_" + rowIndex + "_" + colIndex + "']");
}



// Body Cell 의 체크박스 / 라디오 체크 상태 문자열
scwin.getCheckedStr = function (rowIndex, colId) {
    let td = scwin.getBodyTd(rowIndex, colId);
    let input = td ? td.querySelector("input") : null;
    if (!input) {
        return "입력 요소 없음";
    }
    return input.checked ? "체크" : "해제";
}



// validation 2 판정 출력 : 전체 Row 의 체크박스 체크 상태 / chk 값 / 라디오 체크 상태 / rdo 값
scwin.btn_checkState_onclick = function () {
    for (let r = 0; r < dlt_bind.getRowCount(); r++) {
        wf_body_bottom.getObj("scwin").setReturnValue("Row " + r + " '" + scwin.getCheckedStr(r, "chk") + "' / '" + dlt_bind.getCellData(r, "chk")
            + "' / '" + scwin.getCheckedStr(r, "rdo") + "' / '" + dlt_bind.getCellData(r, "rdo") + "'");
    }
}



// validation 1 판정 출력 : 전체 Row 의 메모(text) 표시값 / 계산(expression) 표시값
scwin.btn_checkDisplay_onclick = function () {
    for (let r = 0; r < dlt_bind.getRowCount(); r++) {
        let tdMemo = scwin.getBodyTd(r, "memo");
        let tdExpr = scwin.getBodyTd(r, "expr");
        wf_body_bottom.getObj("scwin").setReturnValue("Row " + r + " '" + (tdMemo ? tdMemo.textContent : "") + "' / '" + (tdExpr ? tdExpr.textContent : "") + "'");
    }
}
